import {idOf,isShiny,clamp} from './model.mjs';
const images=new Map(),pending=new Map(),remote=new Map(),tiles=new Map();
export const COLORS={fire:['#ff6b42','#ffc36b','#fff3b8'],water:['#328ef2','#83dfff','#e2ffff'],grass:['#57b95f','#b8ed82','#efffc5'],electric:['#ffcb35','#ffef86','#ffffff'],ghost:['#8955cc','#bd9bf4','#f5e7ff'],psychic:['#d45eb5','#f8a5df','#fff1fa'],ice:['#56c4dd','#b8f3ff','#ffffff'],normal:['#b6a38b','#e1d5bf','#fffaf1']};
export const TYPE_NAMES={normal:'Normal',fire:'Feu',water:'Eau',grass:'Plante',electric:'Électrik',ice:'Glace',fighting:'Combat',poison:'Poison',ground:'Sol',flying:'Vol',psychic:'Psy',bug:'Insecte',rock:'Roche',ghost:'Spectre',dragon:'Dragon',dark:'Ténèbres',steel:'Acier',fairy:'Fée'};
export function loadImage(src){if(!images.has(src)){const im=new Image();im.decoding='async';im.crossOrigin='anonymous';im.src=src;images.set(src,im)}return images.get(src)}
export function icon(key){const id=idOf(key);return !isShiny(key)&&window.PMD_DATA?.[id]?`assets/pmd/${id}/icon.png`:`https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${isShiny(key)?'shiny/':''}${id}.png`}
export async function ensureSprite(key){key=String(key);if((!isShiny(key)&&window.PMD_DATA?.[idOf(key)])||remote.has(key))return;if(pending.has(key))return pending.get(key);const task=(async()=>{const base=`https://raw.githubusercontent.com/PMDCollab/SpriteCollab/master/sprite/${String(idOf(key)).padStart(4,'0')}/${isShiny(key)?'0000/0001/':''}`;try{const response=await fetch(base+'AnimData.xml',{signal:AbortSignal.timeout(8000)});if(!response.ok)return;const xml=new DOMParser().parseFromString(await response.text(),'text/xml'),all=[...xml.querySelectorAll('Anim')],set={};for(const kind of ['Idle','Walk','Attack','Hurt']){let a=all.find(a=>a.querySelector('Name')?.textContent===kind);const copy=a?.querySelector('CopyOf')?.textContent;if(copy)a=all.find(a=>a.querySelector('Name')?.textContent===copy);if(!a)continue;const w=+a.querySelector('FrameWidth')?.textContent,h=+a.querySelector('FrameHeight')?.textContent,durations=[...a.querySelectorAll('Duration')].map(n=>+n.textContent/60);if(!w||!h)continue;const url=base+(copy||kind)+'-Anim.png';set[kind]={w,h,frames:durations.length,rows:8,durations,url};loadImage(url)}if(set.Idle)remote.set(key,set)}catch{/* Static sprite remains available when the sheet server is unreachable. */}})();pending.set(key,task);return task}
export function preload(keys){for(const key of keys){ensureSprite(key);const set=window.PMD_DATA?.[idOf(key)];if(!isShiny(key)&&set)for(const kind of Object.keys(set))loadImage(`assets/pmd/${idOf(key)}/${kind}.png`);loadImage(icon(key))}}
export function drawMon(ctx,key,x,y,size=60,kind='Idle',dir=0,time=0){ensureSprite(key);const set=(!isShiny(key)&&window.PMD_DATA?.[idOf(key)])||remote.get(String(key)),d=set?.[kind]||set?.Idle;ctx.save();ctx.imageSmoothingEnabled=false;if(d){const mode=set[kind]?kind:'Idle',im=loadImage(d.url||`assets/pmd/${idOf(key)}/${mode}.png`);if(im.complete&&im.naturalWidth){const frames=Math.max(1,Math.floor(im.naturalWidth/d.w));let frame=Math.floor(time*(kind==='Attack'?13:kind==='Walk'?9:5))%frames;if(d.durations?.length){let t=time%d.durations.reduce((a,b)=>a+b,0);frame=0;while(frame<d.durations.length-1&&t>d.durations[frame])t-=d.durations[frame++]}const scale=size/Math.max(d.w,d.h);ctx.drawImage(im,frame*d.w,clamp(dir,0,Math.floor(im.naturalHeight/d.h)-1)*d.h,d.w,d.h,Math.round(x-d.w*scale/2),Math.round(y-d.h*scale/2),d.w*scale,d.h*scale);ctx.restore();if(isShiny(key))sparkle(ctx,x,y,size,time);return}}const im=loadImage(icon(key));if(im.complete&&im.naturalWidth){ctx.drawImage(im,Math.round(x-size/2),Math.round(y-size/2),size,size)}else{ctx.fillStyle='#dbb26f';ctx.fillRect(x-8,y-10,16,16);ctx.fillStyle='#492c40';ctx.fillRect(x-8,y-2,16,5);ctx.fillStyle='#fff2d1';ctx.fillRect(x-2,y-2,4,4)}ctx.restore();if(isShiny(key))sparkle(ctx,x,y,size,time)}
export function sparkle(ctx,x,y,size,time){ctx.fillStyle='#fff5b0';for(let i=0;i<3;i++){const a=time*1.6+i*2.09,xx=Math.round(x+Math.cos(a)*size*.38),yy=Math.round(y+Math.sin(a)*size*.32);ctx.globalAlpha=.4+.5*Math.sin(time*4+i)**2;ctx.fillRect(xx-3,yy,7,1);ctx.fillRect(xx,yy-3,1,7)}ctx.globalAlpha=1}
export function direction(dx,dy){return dx||dy?[2,3,4,5,6,7,0,1][Math.round((Math.atan2(dy,dx)+Math.PI)/(Math.PI/4))%8]:0}
export function noise(x,y){let n=(x*374761393+y*668265263)^0x9e3779b9;n=Math.imul(n^(n>>>13),1274126177);return((n^(n>>>16))>>>0)/4294967296}
function tile(index){if(tiles.has(index))return tiles.get(index);const c=document.createElement('canvas');c.width=c.height=32;const x=c.getContext('2d');x.fillStyle=['#333336','#373437','#303337','#3a3537'][index%4];x.fillRect(0,0,32,32);for(let i=0;i<50;i++){x.fillStyle=['#414044','#454044','#292c31','#4c4846'][i%4];x.fillRect(Math.floor(noise(i,index)*32),Math.floor(noise(index,i)*32),i%3+1,1)}x.fillStyle='#232830';x.fillRect(0,0,32,1);x.fillRect(0,0,1,32);tiles.set(index,c);return c}
export function drawChest(ctx,x,y,opened=false,t=0){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.fillStyle='#0b0d14';ctx.fillRect(-17,-12,34,28);ctx.fillStyle='#5a3742';ctx.fillRect(-15,-10,30,23);ctx.fillStyle='#a76b42';ctx.fillRect(-14,-10,28,7);ctx.fillStyle='#e3b96f';ctx.fillRect(-14,-3,28,3);ctx.fillRect(-11,-10,3,23);ctx.fillRect(8,-10,3,23);ctx.fillRect(-3,-2,6,8);ctx.fillStyle=opened?'#14131b':'#f7d99b';ctx.fillRect(-11,-8,22,3);if(opened){ctx.fillStyle='#231a25';ctx.fillRect(-11,-12,22,7);ctx.fillStyle='#a76b42';ctx.fillRect(-15,-18,30,5)}else if(Math.sin(t*3)>0){ctx.fillStyle='#ffe4a0';ctx.fillRect(20,-21,2,7);ctx.fillRect(17,-18,8,2)}ctx.restore()}
export function terrain(ctx,cx,cy,w,h,time=0){ctx.imageSmoothingEnabled=false;for(let y=Math.floor(cy/32);y<=Math.floor((cy+h)/32);y++)for(let x=Math.floor(cx/32);x<=Math.floor((cx+w)/32);x++){const xx=x*32-cx,yy=y*32-cy;ctx.drawImage(tile(Math.floor(noise(x,y)*8)),xx,yy);const n=noise(x+99,y+44);if(n>.94){ctx.fillStyle='#1e222a';ctx.fillRect(xx+4,yy+8,20,3);ctx.fillRect(xx+19,yy+10,3,10);if(n>.98){ctx.fillStyle=Math.sin(time*2+x+y)>.2?'#bf6949':'#854c40';ctx.fillRect(xx+4,yy+9,14,1)}}}
 // Low ruins and crystals are scenery, never invisible collision walls.
 for(let gy=Math.floor((cy-60)/128);gy<Math.ceil((cy+h+60)/128);gy++)for(let gx=Math.floor((cx-60)/128);gx<Math.ceil((cx+w+60)/128);gx++){const n=noise(gx+21,gy+51);if(n<.65)continue;const x=gx*128+noise(gx,gy)*46-cx,y=gy*128+noise(gy,gx)*46-cy;ctx.fillStyle='#151b25';ctx.fillRect(x-15,y-6,34,15);if(n>.9){ctx.fillStyle='#423448';ctx.fillRect(x-9,y-28,10,33);ctx.fillStyle='#b57bba';ctx.fillRect(x-7,y-26,4,21);ctx.fillStyle='#7a9cbd';ctx.fillRect(x+4,y-16,8,21);ctx.fillStyle='#b7c8d5';ctx.fillRect(x+5,y-15,2,10)}else{ctx.fillStyle='#4d4c4c';ctx.fillRect(x-12,y-17,26,22);ctx.fillStyle='#69615b';ctx.fillRect(x-10,y-20,23,6);ctx.fillStyle='#242a32';ctx.fillRect(x-11,y-3,23,2);ctx.fillRect(x+3,y-17,2,12)}}}
export function flame(ctx,x,y,size,t,color='#ef8c4b'){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.fillStyle='#793637';ctx.fillRect(-size*.5,-size,size,size);ctx.fillStyle=color;const phase=Math.floor(t*8)%3;ctx.fillRect(-size*.35,-size*(1.2+phase*.08),size*.7,size*1.15);ctx.fillStyle='#ffdf8e';ctx.fillRect(-size*.15,-size*.7,size*.3,size*.7);ctx.restore()}
export function towerScene(ctx,w,h,t=0){ctx.imageSmoothingEnabled=false;ctx.fillStyle='#141927';ctx.fillRect(0,0,w,h);for(let y=0;y<h*.75;y+=10){ctx.fillStyle=`rgba(126,58,66,${.025+y/h*.02})`;ctx.fillRect(0,y,w,10)}const mx=w*.64;ctx.fillStyle='#d9b6a0';ctx.fillRect(mx+110,90,40,40);ctx.fillStyle='#141927';ctx.fillRect(mx+100,80,33,39);for(let layer=0;layer<3;layer++){ctx.fillStyle=['#292733','#242632','#1b222d'][layer];for(let i=0;i<12;i++){const x=i*w/10,y=h*(.48+layer*.13)-noise(i,layer)*80;ctx.beginPath();ctx.moveTo(x-100,h);ctx.lineTo(x,y);ctx.lineTo(x+110,h);ctx.fill()}}ctx.fillStyle='#0c1521';ctx.fillRect(0,h*.86,w,h*.14);for(let i=0;i<5;i++){ctx.fillStyle=i%2?'#d46d48':'#733a3e';ctx.fillRect(w*.45+i*3,h*.88+i*3,w*.52-i*6,2)}
 const x=Math.floor(mx-55),base=h*.85,top=h*.25;ctx.fillStyle='#111722';ctx.fillRect(x-18,base-28,150,45);ctx.fillStyle='#272b36';ctx.fillRect(x,top,112,base-top);ctx.fillStyle='#3f3942';ctx.fillRect(x,top,15,base-top);ctx.fillStyle='#19202b';ctx.fillRect(x+95,top,17,base-top);for(let yy=top+8;yy<base;yy+=13){ctx.fillStyle='#181e29';ctx.fillRect(x+3,yy,106,2);for(let xx=0;xx<5;xx++){ctx.fillStyle='#47404a';ctx.fillRect(x+5+xx*22+(yy%2?8:0),yy+4,1,8)}}for(let floor=0;floor<5;floor++){const yy=top+23+floor*(base-top-45)/5;ctx.fillStyle='#121725';ctx.fillRect(x+44,yy,23,28);ctx.fillStyle='#c37a54';ctx.fillRect(x+49,yy+4,12,20);ctx.fillStyle='#ffce83';ctx.fillRect(x+51,yy+5,4,17);ctx.fillStyle='#6b4545';ctx.fillRect(x+55,yy+4,2,20);ctx.fillRect(x+49,yy+13,12,2);ctx.fillStyle='#4b434a';ctx.fillRect(x-8,yy+31,128,5)}ctx.fillStyle='#292c38';ctx.fillRect(x-9,top-16,130,18);for(let i=0;i<7;i++){ctx.fillStyle='#58505b';ctx.fillRect(x-8+i*20,top-29,12,19);ctx.fillStyle='#8a6a65';ctx.fillRect(x-8+i*20,top-29,12,3)}ctx.fillStyle='#101421';ctx.fillRect(x+34,base-41,45,43);ctx.fillStyle='#bc7952';ctx.fillRect(x+32,base-42,4,44);ctx.fillRect(x+77,base-42,4,44);ctx.fillRect(x+34,base-44,45,4);for(let step=0;step<7;step++){ctx.fillStyle=step%2?'#5b4b4c':'#413e47';ctx.fillRect(x+27-step*4,base+step*4,60+step*8,4)}flame(ctx,x+16,base-5,11,t);flame(ctx,x+97,base-5,11,t+.6);for(let i=0;i<40;i++){const xx=noise(i,2)*w,yy=h-((t*(8+noise(i,4)*15)+noise(i,5)*h)%h);ctx.fillStyle=i%3?'#d79361':'#f5cd8c';ctx.globalAlpha=.25+noise(i,6)*.5;ctx.fillRect(xx,yy,i%4===0?2:1,2)}ctx.globalAlpha=1}
export function projectile(ctx,b,cx,cy){const colors=COLORS[b.type]||COLORS.normal;ctx.save();for(let i=0;i<(b.trail||[]).length;i++){const p=b.trail[i];ctx.globalAlpha=(i+1)/8;ctx.fillStyle=colors[0];ctx.fillRect(p.x-cx-3,p.y-cy-3,6,6)}ctx.globalAlpha=1;const x=Math.round(b.x-cx),y=Math.round(b.y-cy);ctx.fillStyle=colors[0];ctx.fillRect(x-5,y-5,10,10);ctx.fillStyle=colors[1];ctx.fillRect(x-3,y-3,6,6);ctx.fillStyle=colors[2];ctx.fillRect(x-1,y-2,2,4);ctx.restore()}
export function hitEffect(ctx,e,cx,cy){const p=1-e.life/e.max,colors=COLORS[e.type]||COLORS.normal;ctx.save();ctx.globalAlpha=1-p;ctx.fillStyle=colors[1];for(let i=0;i<10;i++){const a=i*Math.PI/5;ctx.fillRect(Math.round(e.x-cx+Math.cos(a)*p*30),Math.round(e.y-cy+Math.sin(a)*p*30),3,3)}ctx.globalAlpha=1;ctx.fillStyle=e.heal?'#9bf2ab':'#ffe6b6';ctx.font='12px PixelLocal,monospace';ctx.textAlign='center';ctx.fillText(e.text||'−'+e.n,e.x-cx,e.y-cy-25-p*17);ctx.restore()}
